import{_ as t,c as a,o,a3 as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Set up Time Off","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/setup/index.md","filePath":"master/human-resources/time-off/setup/index.md","lastUpdated":1793074831000}'),r={name:"master/human-resources/time-off/setup/index.md"};function d(i,e,l,n,h,u){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="set-up-time-off" tabindex="-1">Set up Time Off <a class="header-anchor" href="#set-up-time-off" aria-label="Permalink to &quot;Set up Time Off&quot;">​</a></h1><p>Setup tells Aureus what kinds of leave exist and which dates are special. You do it once, then adjust it when your policy changes. Three pages hold the setup, all under <strong>Configuration</strong>.</p><blockquote><p><strong>In simple words:</strong> Setup is where you name the kinds of leave and list the days off for everyone.</p></blockquote><h2 id="the-three-setup-pages" tabindex="-1">The three setup pages <a class="header-anchor" href="#the-three-setup-pages" aria-label="Permalink to &quot;The three setup pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Menu path</th><th>What it is</th></tr></thead><tbody><tr><td><a href="./time-off-types.html">Leave types</a></td><td><code>Time Off → Configuration → Leave Types</code></td><td>The kinds of leave people can request, and the rules of each</td></tr><tr><td><a href="./public-holidays.html">Public holidays</a></td><td><code>Time Off → Configuration → Public Holidays</code></td><td>Days off for the whole company, such as New Year&#39;s Day</td></tr><tr><td><a href="./mandatory-days.html">Mandatory days</a></td><td><code>Time Off → Configuration → Mandatory Holidays</code></td><td>Days when the company expects everyone to be at work</td></tr></tbody></table><h2 id="how-they-relate" tabindex="-1">How they relate <a class="header-anchor" href="#how-they-relate" aria-label="Permalink to &quot;How they relate&quot;">​</a></h2><p>A leave type is a rule book for requests. Choose it on every request and every allocation. It decides who approves and whether days must be given first.</p><p>Public holidays and mandatory days are lists of dates. Staff see them in the <strong>Holidays</strong> window on <code>Time Off → My Time → Dashboard</code>. They do not change the <strong>Duration</strong> of a request. <strong>Duration</strong> skips Saturdays and Sundays only.</p><div class="info custom-block"><p class="custom-block-title">Order</p><p>Create leave types first. Allocations and requests need them. Add holidays and mandatory days whenever you like.</p></div><h2 id="seeded-data" tabindex="-1">Seeded data <a class="header-anchor" href="#seeded-data" aria-label="Permalink to &quot;Seeded data&quot;">​</a></h2><ul><li>Seven leave types, such as <strong>Paid Time Off</strong> and <strong>Sick Time Off</strong>.</li><li>A few public holidays and one mandatory day, <strong>Company Anniversary</strong>. Sample dates may be from a past year.</li></ul><h2 id="typical-setup-order" tabindex="-1">Typical setup order <a class="header-anchor" href="#typical-setup-order" aria-label="Permalink to &quot;Typical setup order&quot;">​</a></h2><ol><li>Review the seven leave types and edit or add yours.</li><li>Add the public holidays of the current year.</li><li>Add mandatory days if you use them.</li><li>Give days to people. See <a href="./../allocations/">Allocations</a>.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Time off overview</a></li><li><a href="./../get-started/first-steps.html">First steps</a></li><li><a href="./../requests/my-time.html">My Time</a></li></ul>',15)]))}const c=t(r,[["render",d]]);export{f as __pageData,c as default};
